	@Override
	public MCCallerPanelBridge createBridge(String id) {
		if (id.equals("MS.MSBEL0060.Srch01")) {
			return new MS_MSBEL0060_Srch01Bridge();
		}
		if (id.equals("MS.MSBEL0060.Srch02")) {
			return new MS_MSBEL0060_Srch02Bridge();
		}
		if (id.equals("MS.MSBEL0060.Srch03")) {
			return new MS_MSBEL0060_Srch03Bridge();
		}
		return super.createBridge(id);
	}
